import React from 'react';
import {useParams,Link,Navigate} from 'react-router-dom';
import Seo from '../components/Seo';
import Icon from '../components/Icon';
import {projects} from '../data/site';
export default function ProjectDetail(){const {slug}=useParams();const p=projects.find(x=>x.slug===slug);if(!p)return <Navigate to="/projets" replace/>;return <>
 <Seo title={p.name} path={`/projets/${p.slug}`} description={p.intro} type="article"/>
 <section className="project-detail-hero"><div className="project-detail-copy"><p className="eyebrow"><span/>{p.kind} · {p.year}</p><h1>{p.name}</h1><p>{p.headline}</p><div className="hero-actions"><a className="primary-action" href={p.url} target="_blank" rel="noopener noreferrer">Voir le projet <Icon name="external"/></a><Link className="glass-action" to="/contact">J’ai un projet</Link></div></div><div className={`project-detail-visual project-media--${p.slug}`} style={p.image?{backgroundImage:`linear-gradient(180deg,rgba(4,8,16,.02),rgba(4,8,16,.42)),url(${p.image})`}:{}}><div className="detail-glass"><span>{p.roles[0]}</span><span>{p.stack[0]}</span></div></div></section>
 <section className="project-detail-body"><aside className="glass-card"><div><p>Rôle</p>{p.roles.map(x=><span key={x}>{x}</span>)}</div><div><p>Technologies</p>{p.stack.map(x=><span key={x}>{x}</span>)}</div></aside><article><div><small>Point de départ</small><h2>{p.challenge}</h2></div><div><small>Choix</small><p>{p.approach}</p></div><div><small>Ce que je travaille ici</small><p>{p.detail}</p></div></article></section>
 <section className="case-next"><Link to="/projets">← Tous les projets</Link><Link to="/contact">J’ai un projet <Icon name="arrow" size={15}/></Link></section>
 </>}
